import { workAsyncStorage } from '../app-render/work-async-storage.external';
import { throwForMissingRequestStore, workUnitAsyncStorage } from '../app-render/work-unit-async-storage.external';
import { applyOwnerStack, makePrefetchHangingPromise, makeUntrackedHangingPromise, RENDER_STAGES_BY_DATA_KIND, trackIncompatibleShellContent } from '../dynamic-rendering-utils';
import { isRequestApiAllowedInCurrentPhase } from './utils';
import { InvariantError } from '../../shared/lib/invariant-error';
import { RenderStage } from '../app-render/staged-rendering';
/**
 * When `partialPrefetching` is enabled, this function allows you to indicate
 * that the subsequent code should be excluded from the shell. It will be deferred until
 * a prefetch (i.e. when using `<Link prefetch={true}>`) or a navigation.
 *
 * It has no effect during static prerendering — static output is computed
 * once and shared across many clients, so there's no per-request cost to
 * save — and no effect on the initial load of a page.
 *
 * Unlike `connection()`, it does not mark the subtree as request-dependent —
 * content below `await prefetch()` remains fully cacheable.
 *
 * Read more: [Next.js Docs: `prefetch`](https://nextjs.org/docs/app/api-reference/functions/prefetch)
 */ export function prefetch() {
    const workStore = workAsyncStorage.getStore();
    const workUnitStore = workUnitAsyncStorage.getStore();
    if (!workStore || !workUnitStore) {
        const callingExpression = 'prefetch';
        throwForMissingRequestStore(callingExpression);
    }
    if (!process.env.__NEXT_CACHE_COMPONENTS) {
        throw new Error(`Route ${workStore.route} used \`prefetch()\`, which requires Cache Components to be enabled. Learn more: https://nextjs.org/docs/app/api-reference/config/next-config-js/cacheComponents`);
    }
    if (!isRequestApiAllowedInCurrentPhase(workUnitStore)) {
        throw new Error(`Route ${workStore.route} used \`prefetch()\` inside \`after()\` while rendering. The \`prefetch()\` function is used to indicate the subsequent code must not run in the app shell, but \`after()\` executes after the request, so this function is not allowed in this scope. See more info here: https://nextjs.org/docs/app/api-reference/functions/after`);
    }
    const stageVariants = RENDER_STAGES_BY_DATA_KIND.staticUrlData.prefetchApi;
    switch(workUnitStore.type){
        case 'prerender':
            {
                // Content below `prefetch()` is excluded from the shell, but it's
                // deliberately included in the static output (and thus in static
                // prefetches), so we only delay it until the static prefetch stage.
                // It resolves in `PrefetchStatic_prefetchApi`, one stage ahead of URL data,
                // so validation can attribute a blocking hole to `prefetch()`.
                const { stagedRendering } = workUnitStore;
